using System.Numerics;using System.Text.Json;using ValveKeyValue;using ValveResourceFormat;using ValveResourceFormat.Blocks;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Utils;
// Item-local effect volumes, carried with the item's mesh through hero merging.
// These named sets are only selected by the cloned unusual particles.
internal static class ItemHitboxScope {
 record Particle(string Input,string Output);
 record Request(string Input,string Output,string HitboxSet,string Report,Particle[] Particles,Dictionary<string,string>? Meshes=null);
 static KVObject A(IEnumerable<KVObject>x)=>KVObject.Array(x);
 static KVObject R(params(string,KVObject)[] fields){var r=KVObject.Collection();foreach(var(k,v)in fields)r[k]=v;return r;}
 static KVObject V(Vector3 v)=>A(new[]{new KVObject(v.X),new KVObject(v.Y),new KVObject(v.Z)});
 static Dictionary<string,Matrix4x4> Poses(Model m){var sk=m.Data["m_modelSkeleton"];var names=sk["m_boneName"].Values.Select(x=>x.ToString(null)).ToArray();var result=new Dictionary<string,Matrix4x4>(StringComparer.OrdinalIgnoreCase);Matrix4x4 Get(int i){if(result.TryGetValue(names[i],out var v))return v;var p=sk["m_bonePosParent"][i].Values.Select(x=>x.ToSingle(null)).ToArray();var q=sk["m_boneRotParent"][i].Values.Select(x=>x.ToSingle(null)).ToArray();var scale=sk.TryGetValue("m_boneScaleParent",out var scales)?scales[i].ToSingle(null):1f;v=Matrix4x4.CreateScale(scale)*Matrix4x4.CreateFromQuaternion(new(q[0],q[1],q[2],q[3]))*Matrix4x4.CreateTranslation(p[0],p[1],p[2]);int parent=sk["m_nParent"][i].ToInt32(null);if(parent>=0)v*=Get(parent);result[names[i]]=v;return v;}for(int i=0;i<names.Length;i++)Get(i);return result;}
 internal static KVObject Boxes(IReadOnlyList<ItemEffectScope.Point> points,IReadOnlyDictionary<string,Matrix4x4> poses){
  var bins=new Dictionary<(string,int,int,int),List<Vector3>>();
  foreach(var p in points){int j=Array.IndexOf(p.Weights,p.Weights.Max());string bone=p.Bones[j];if(!poses.TryGetValue(bone,out var pose)||!Matrix4x4.Invert(pose,out var inv))throw new InvalidDataException("Unbound effect bone: "+bone);var local=Vector3.Transform(p.Position,inv);var key=(bone,(int)MathF.Floor(local.X/10),(int)MathF.Floor(local.Y/10),(int)MathF.Floor(local.Z/10));if(!bins.TryGetValue(key,out var list))bins[key]=list=new();list.Add(local);}
