 }
 internal static int Patch(KVObject data,string set){
  if(!data.TryGetValue("m_Initializers",out var inits))return 0;int changed=0;
  foreach(var op in inits.Values)if(op.TryGetValue("_class",out var cls)&&cls.ToString(null)=="C_INIT_CreateOnModel"){
   if(op.TryGetValue("m_modelInput",out var input)&&((input.TryGetValue("m_nType",out var type)&&type.ToString(null)!="PM_TYPE_CONTROL_POINT")||(input.TryGetValue("m_nControlPoint",out var cp)&&cp.ToInt32(null)!=0)))throw new InvalidDataException("Effect samples another model; explicit binding profile required");
   op["m_bUseMesh"]=new KVObject(false);op["m_bUseBones"]=new KVObject(false);op["m_HitboxSetName"]=new KVObject(set);changed++;
  }
  if(changed==0)return 0;
  var ops=data.TryGetValue("m_Operators",out var old)?old:KVObject.Array();
  var keep=ops.Values.Where(op=>!op.TryGetValue("_class",out var c)||c.ToString(null) is not("C_OP_SnapshotSkinToBones" or "C_OP_SnapshotRigidSkinToBones" or "C_OP_MovementRigidAttachToCP" or "C_OP_LockToBone"));
  data["m_Operators"]=A(keep.Concat(new[]{R(("_class",new KVObject("C_OP_LockToBone")),("m_HitboxSetName",new KVObject(set)),("m_bUseBones",new KVObject(false)),("m_bRigid",new KVObject(true)),("m_flLifeTimeFadeStart",new KVObject(1f)),("m_flLifeTimeFadeEnd",new KVObject(1f)),("m_flJumpThreshold",new KVObject(100000f)),("m_flPrevPosScale",new KVObject(1f)),("m_nFieldOutput",new KVObject(0)),("m_nFieldOutputPrev",new KVObject(2)))}));return changed;
 }
 public static void Run(string manifest){var q=JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Empty item hitbox request");if(!System.Text.RegularExpressions.Regex.IsMatch(q.HitboxSet,"^harlord_fx_[a-f0-9]{24}$")||q.Particles.Length>256)throw new InvalidDataException("Invalid effect set or particle count");var temporary=new List<string>();var resources=new List<Resource>();try{
  int changed=0;var particles=new List<(Particle File,Resource Resource,byte[] Bytes)>();foreach(var p in q.Particles){var r=new Resource{FileName=p.Input};resources.Add(r);r.Read(p.Input);if(r.DataBlock is not ParticleSystem particle)throw new InvalidDataException("Expected particle system");changed+=Patch(particle.Data,q.HitboxSet);particles.Add((p,r,File.ReadAllBytes(p.Input)));}
  int pointCount=0,boxCount=0;string[] bones=[];
  if(changed>0){var meshes=q.Meshes?.ToDictionary(p=>p.Key.EndsWith("_c")?p.Key:p.Key+"_c",p=>p.Value);var input=ModelMerge.EmbedExternalMeshes(q.Input,meshes,temporary);var bytes=File.ReadAllBytes(input);using var r=new Resource{FileName=input};r.Read(input);var model=r.DataBlock as Model??throw new InvalidDataException("Expected item model");var points=ItemEffectScope.Geometry(model,model);var boxes=Boxes(points,Poses(model));pointCount=points.Count;boxCount=boxes.Count;bones=boxes.Values.Select(b=>b["m_sBoneName"].ToString(null)).Distinct().Order().ToArray();
   // Put the set on a selected LOD0 mesh, so normal merge filtering retains it.
   ulong Mask(KVObject v){var t=v.ToString(System.Globalization.CultureInfo.InvariantCulture);return t.StartsWith('-')?unchecked((ulong)long.Parse(t)):ulong.Parse(t);}
   var masks=model.Data["m_refMeshGroupMasks"].Values.ToArray();var selected=Mask(model.Data["m_nDefaultMeshGroupMask"]);var meshIndex=model.GetEmbeddedMeshesForLod(0).First(m=>m.Item2>=masks.Length||(Mask(masks[m.Item2])&selected)!=0).Item2;var cb=r.Blocks.Single(b=>b.Type==BlockType.CTRL);BinaryKV3 Read(Block b){var k=new BinaryKV3(b.Type){Resource=r,Offset=b.Offset,Size=b.Size};using var reader=new BinaryReader(new MemoryStream(bytes));reader.BaseStream.Position=b.Offset;k.Read(reader);return k;}var ctrl=Read(cb);var row=ctrl.Data.Root["embedded_meshes"].Values.Single(v=>v[v.ContainsKey("m_nMeshIndex")?"m_nMeshIndex":"mesh_index"].ToInt32(null)==meshIndex);var block=r.Blocks[row[row.ContainsKey("m_nDataBlock")?"m_nDataBlock":"data_block"].ToInt32(null)];var kv=Read(block);var prior=kv.Data.Root.TryGetValue("m_hitboxsets",out var oldsets)?oldsets.Values:Enumerable.Empty<KVObject>();kv.Data.Root["m_hitboxsets"]=A(prior.Where(s=>s["key"].ToString(null)!=q.HitboxSet).Concat(new[]{R(("key",new KVObject(q.HitboxSet)),("value",R(("m_name",new KVObject(q.HitboxSet)),("m_nNameHash",new KVObject(StringToken.Get(q.HitboxSet))),("m_HitBoxes",boxes))))}));var raw=HeroActivityRules.SerializeActivity(kv,bytes[(int)block.Offset]);using(var output=File.Create(q.Output))Program.SerializePatchedResource(r,bytes,output,false,preserveMetadata:true,rawBlocks:new Dictionary<object,byte[]>{{block,raw}});using var check=new Resource{FileName=q.Output};check.Read(q.Output);if(!((Model)check.DataBlock!).GetEmbeddedMeshesForLod(0).Any(m=>m.Mesh.Data.TryGetValue("m_hitboxsets",out var sets)&&sets.Values.Any(s=>s["key"].ToString(null)==q.HitboxSet)))throw new InvalidDataException("Effect hitbox set did not survive writing");
  }else File.Copy(q.Input,q.Output,true);
  foreach(var(p,r,bytes)in particles){using(var output=File.Create(p.Output))Program.SerializePatchedResource(r,bytes,output,true,preserveMetadata:true);using var check=new Resource{FileName=p.Output};check.Read(p.Output);}
  File.WriteAllText(q.Report,JsonSerializer.Serialize(new{version=2,applied=changed>0,initializers=changed,pointCount,boxCount,bones,hitboxSet=q.HitboxSet,sourceKind="item-hitboxes"}));
 }finally{foreach(var r in resources)r.Dispose();foreach(var f in temporary)File.Delete(f);}}
}
